@Service
public class BookService {
  private final BookRepository repository;

  public BookService(BookRepository repository) {
    this.repository = repository;
  }
}

@SpringBootApplication
public class ApiApplication {
  public static void main(String[] args) {
    SpringApplication.run(ApiApplication.class, args);
  }
}

@GetMapping("/{id}")
public BookResponse findById(@PathVariable long id) {
  return service.findById(id);
}

@Transactional
public BookResponse create(CreateBookCommand command) {
  Book book = Book.create(command.title(), command.author());
  return BookResponse.from(repository.save(book));
}

public interface BookJpaRepository
    extends JpaRepository<BookEntity, Long> {
  List<BookEntity> findByAvailableTrueOrderByTitle();
}

@Entity
@Table(name = "books")
class BookEntity {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  private String title;

  protected BookEntity() {}
}

@Transactional
public void rename(long id, String title) {
  BookEntity entity = repository.findById(id)
      .orElseThrow(BookNotFoundException::new);
  entity.rename(title);
}

public record CreateBookRequest(
    @NotBlank
    @Size(max = 200)
    String title,

    @NotBlank
    String author
) {}

@ExceptionHandler(BookNotFoundException.class)
ResponseEntity<ApiError> handleNotFound(
    BookNotFoundException error
) {
  return ResponseEntity.status(404)
      .body(new ApiError("BOOK_NOT_FOUND", error.getMessage()));
}

@PreAuthorize("hasRole('ADMIN')")
@DeleteMapping("/{id}")
public ResponseEntity<Void> delete(@PathVariable long id) {
  service.delete(id);
  return ResponseEntity.noContent().build();
}
